import { mcbrideSourceRows } from './mcbrideSourceRows';

export type DisabilityStandard = {
  readonly title: string;
  readonly result: string;
  readonly condition: string;
  readonly source: string;
  readonly details?: readonly DisabilityDetailRow[];
  readonly criteria?: readonly string[];
  readonly mcbrideEstimate?: McbrideEstimate;
};

export type McbrideEstimateScenario = {
  readonly label: string;
  readonly rate: string;
  readonly probability: number;
  readonly duration: string;
  readonly condition: string;
};

export type McbrideEstimate = {
  readonly defaultScenario: McbrideEstimateScenario;
  readonly surgeryScenario: McbrideEstimateScenario;
  readonly nerveScenario: McbrideEstimateScenario;
  readonly note: string;
};

export type DisabilityDetailRow = {
  readonly level: string;
  readonly condition: string;
  readonly measurement?: string;
  readonly reference?: string;
};

export type DisabilityCatalogEntry = {
  readonly id: string;
  readonly diagnosis: string;
  readonly aliases: readonly string[];
  readonly kcd: readonly string[];
  readonly bodyPart: string;
  readonly standards: readonly DisabilityStandard[];
};

const industrialSource = '산업재해보상보험법 시행규칙 별표 5 장해등급 기준';
