const insuranceAdlsSource = '보험업감독업무시행세칙 [별표 15] ADLS(일상생활 기본동작) 기준';
const mcbrideSource = '맥브라이드 장해율표 일반 직업 참고표';

const entry = (
  id: string, diagnosis: string, aliases: string[], kcd: string[], bodyPart: string,
  industrial: string, industrialCondition: string, insurance: string, insuranceCondition: string,
  mcbride: string, mcbrideCondition: string
): DisabilityCatalogEntry => ({
  id, diagnosis, aliases, kcd, bodyPart,
  standards: [
    { title: '산재 후유장해', result: industrial, condition: industrialCondition, source: industrialSource },
    { title: '제3보험 약관상 장해', result: insurance, condition: insuranceCondition, source: insuranceSource },
    { title: '맥브라이드 예상', result: mcbride, condition: mcbrideCondition, source: mcbrideSource }
  ]
});

