function parseRange(value: string, suffix: string) {
  const match = new RegExp(`(\\d+)~(\\d+)${suffix}`).exec(value);
  if (!match) return [];
  const start = Number(match[1]);
  const end = Number(match[2]);
  return Array.from({ length: end - start + 1 }, (_, index) => start + index);
}

function parseRateRange(value: string) {
  return parseRange(value, '% 후보');
}

